# -*- coding: utf-8 -*-
"""MANAPRINT — UNITÉ · 5 boules (RANIHEI) · maquette Canva de Maeva (27/11/2026, « unite_canva_12_A4 »).
Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE (3 x 4), traits de coupe en pointillés.
Chaque billet : UNITÉ, le bouquet, les mains et la colombe, cinq cœurs en V (dessins Canva posés
en pochoir : en couleur, MANAPRINT les repeint, les chiffres restent noirs), RANIHEI SISTERS & SHOP
87 77 39 19, ranihei.sisters0913@gmail.com, la SÉRIE.
RÈGLE (celle d'UNITÉ, inchangée — sceau Maeva 15/08) : un numéro par cœur —
   haut-gauche 1-15 · haut-droite 16-25 · milieu-gauche 26-40 · milieu-droite 41-60 ·
   centre en bas 61-75.   Crieur : 1 à 75.
Chiffres Helvetica gras 30 pt noirs, comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
POLICE_NUM = "Helvetica-Bold"
TAILLE_NUM = 30
# (centre x, ligne de base) : haut-gauche 1-15 · haut-droite 16-25 · milieu-gauche 26-40 ·
#                              milieu-droite 41-60 · centre en bas 61-75
CASES = [(34.578, 108.133), (246.043, 108.133), (86.452, 76.102), (194.169, 76.102), (140.310, 42.653)]
# (x, y, largeur, hauteur, n° du dessin) : bouquet, mains, colombe, puis les 5 cœurs
_IMGS = [(129.3467, 89.29134, 21.93651, 30.04724, 0), (8.503937, 17.5748, 36.0591, 45.35433, 1),
         (234.1417, 33.44882, 33.92324, 38.55118, 2), (3.401575, 87.85655, 62.3622, 55.85998, 3),
         (214.8661, 87.85655, 62.3622, 55.85998, 3), (55.27559, 55.82506, 62.3622, 55.85998, 3),
         (162.9921, 55.82506, 62.3622, 55.85998, 3), (109.1339, 22.37624, 62.3622, 55.85998, 3)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = (rng.randint(1, 15), rng.randint(16, 25), rng.randint(26, 40), rng.randint(41, 60),
             rng.randint(61, 75))
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_unite_modele", False):
        return
    import base64
    d = _DESSIN
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("UNITE_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G")
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h, k = _IMGS[i]
            _masque.poser(c, "UNITE_IMG_%d" % k, base64.b64decode(_PNG[k]), x, y, w, h)
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._unite_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("UNITE_CANVA")
    _txt(c, "S\u00c9RIE %03d" % serie, 12.47244, 9.637795, "Helvetica-Bold", 5.6, colors.Color(.25, .25, .25))
    for (x, y), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, TAILLE_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("UNITÉ · 5 boules")
    rng = random.Random(int(serie_start) * 100003 + 2719)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


_DESSIN = '.35 .35 .35 RG\n.9 w\nn\n10.77165 2.834646 m\n269.8583 2.834646 l\n274.2458 2.834646 277.7953 6.384076 277.7953 10.77165 c\n277.7953 138.0472 l\n277.7953 142.4348 274.2458 145.9843 269.8583 145.9843 c\n10.77165 145.9843 l\n6.384076 145.9843 2.834646 142.4348 2.834646 138.0472 c\n2.834646 10.77165 l\n2.834646 6.384076 6.384076 2.834646 10.77165 2.834646 c\nh\nS\n0 0 0 rg\nq\nBT 1 0 0 1 0 0 Tm 1.6 Tc 1 0 0 1 116.8827 126.1417 Tm /{H} 15 Tf 18 TL (UNIT\\311) Tj ET\nQ\n@IMG0@\n@IMG1@\n@IMG2@\n@IMG3@\n.1 .1 .1 rg\n@IMG4@\n.1 .1 .1 rg\n@IMG5@\n.1 .1 .1 rg\n@IMG6@\n.1 .1 .1 rg\n@IMG7@\n.1 .1 .1 rg\n.25 .25 .25 rg\n.35 .35 .35 rg\nBT 1 0 0 1 247.1813 18.70866 Tm /{H} 4.4 Tf 5.28 TL (87 77 39 19) Tj T* ET\nBT 1 0 0 1 208.9777 13.32283 Tm /{H} 4.4 Tf 5.28 TL (ranihei.sisters0913@gmail.com) Tj T* ET\nBT 1 0 0 1 206.5263 24.09449 Tm /{HB} 5 Tf 6 TL (RANIHEI SISTERS & SHOP) Tj T* ET'
_PNG = ['', '', '', '']
